def load_csv_as_layer(filepath, encoding='utf-8'):
    """使用QGIS的delimitedtext provider加载CSV"""
    uri = f"file:///{filepath}?delimiter=,&encoding={encoding}&xField=x&yField=y"
    layer = QgsVectorLayer(uri, "temp", "delimitedtext")
    if not layer.isValid():
        # 尝试另一种uri格式（没有坐标的纯属性表）
        uri = f"file:///{filepath}?delimiter=,&encoding={encoding}"
        layer = QgsVectorLayer(uri, "temp", "delimitedtext")
    return layer

def read_csv_via_qgis(filepath):
    """通过QGIS矢量图层读取CSV，尝试多种编码"""
    encodings = ['utf-8-sig', 'utf-8', 'gbk', 'gb18030']
    for enc in encodings:
        try:
            layer = load_csv_as_layer(filepath, enc)
            if layer.isValid() and layer.featureCount() > 0:
                fields = [f.name() for f in layer.fields()]
                rows = []
                for feat in layer.getFeatures():
                    row = {}
                    for fld in fields:
                        row[fld] = feat[fld]
                    rows.append(row)
                return rows, enc, fields
        except:
            continue
    raise RuntimeError(f"无法读取文件: {filepath}")

# 读取符号表
