import json
from qgis.core import QgsVectorLayer, QgsProject, QgsSettings

point_csv = "F:/files/marching-route-data/关键点表_points_MVP_匹配地级城市驻地图层.csv"
symbol_csv = "F:/files/marching-route-data/符号样式表_symbol_styles_匹配地级城市驻地图层.csv"

def read_csv_via_delimitedtext(filepath):
    """使用QGIS delimitedtext provider读取CSV（无几何的纯属性表）"""
    # 使用正斜杠并用file://协议
    fs_path = filepath.replace("\\", "/")
    uri = f"file:///{fs_path}?delimiter=,&crs=EPSG:4326&xField=x&yField=y&encoding=UTF-8"

    # 尝试无几何的纯属性表（不需要x/y）
    uri2 = f"file:///{fs_path}?delimiter=,&encoding=UTF-8&geomType=none"

    for uri_try, desc in [(uri2, "无几何"), (uri, "有几何")]:
        layer = QgsVectorLayer(uri_try, "temp", "delimitedtext")
        if layer.isValid():
            fields = [f.name() for f in layer.fields()]
            if len(fields) > 0 and layer.featureCount() > 0:
                rows = []
                for feat in layer.getFeatures():
                    row = {}
                    for fld in fields:
                        val = feat[fld]
                        # 处理QGIS的NULL值
                        if val is None:
                            row[fld] = None
                        else:
                            row[fld] = str(val)
                    rows.append(row)
                return rows, fields
    raise RuntimeError(f"所有URI格式均无法加载: {filepath}")

# 尝试多种编码
def try_all_encodings(filepath):
    encodings = ['UTF-8', 'UTF-8-SIG', 'GBK', 'GB18030', 'System']
    last_err = None
    for enc in encodings:
        try:
            fs_path = filepath.replace("\\", "/")
            uri = f"file:///{fs_path}?delimiter=,&encoding={enc}&geomType=none"
            layer = QgsVectorLayer(uri, "temp", "delimitedtext")
            if layer.isValid() and layer.featureCount() > 0:
                fields = [f.name() for f in layer.fields()]
                if len(fields) > 0:
                    rows = []
                    for feat in layer.getFeatures():
                        row = {}
                        for fld in fields:
                            val = feat[fld]
                            row[fld] = str(val) if val is not None else None
                        rows.append(row)
                    return rows, enc, fields
        except Exception as e:
            last_err = e
            continue
    raise RuntimeError(f"无法读取 {filepath}: {last_err}")

print("读取符号表...")
symbol_rows, symbol_enc, symbol_fields = try_all_encodings(symbol_csv)
print(f"  编码: {symbol_enc}, 字段: {symbol_fields}, 行数: {len(symbol_rows)}")

print("读取点表...")
point_rows, point_enc, point_fields = try_all_encodings(point_csv)
print(f"  编码: {point_enc}, 字段: {point_fields}, 行数: {len(point_rows)}")

# 数值类型转换
for row in symbol_rows:
